CREATE TABLE IF NOT EXISTS panel_runtime (id INT PRIMARY KEY, heartbeat DATETIME NULL, online_players INT NOT NULL DEFAULT 0, sessions INT NOT NULL DEFAULT 0, threads INT NOT NULL DEFAULT 0, ram_used BIGINT NOT NULL DEFAULT 0, ram_max BIGINT NOT NULL DEFAULT 0, cpu DOUBLE NULL, maintenance TINYINT NOT NULL DEFAULT 0);
INSERT IGNORE INTO panel_runtime(id) VALUES(1);
CREATE TABLE IF NOT EXISTS panel_command (id BIGINT AUTO_INCREMENT PRIMARY KEY, action VARCHAR(30) NOT NULL, player_id BIGINT NULL, requested_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, completed_at DATETIME NULL, result VARCHAR(255) NULL);
CREATE TABLE IF NOT EXISTS panel_vnd_audit (id BIGINT AUTO_INCREMENT PRIMARY KEY, request_key VARCHAR(64) NOT NULL UNIQUE, admin_id INT NOT NULL, player_id BIGINT NOT NULL, account_id INT NOT NULL, amount INT NOT NULL, balance_before INT NOT NULL, balance_after INT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, undone_at DATETIME NULL);
CREATE TABLE IF NOT EXISTS panel_skill_rate (skill_id INT PRIMARY KEY, multiplier DOUBLE NOT NULL DEFAULT 1);
